/* Auto-generated sample data for dbo.RoomOccupancy, derived from the real room/bed
   inventory captured in the original Room Occupancy prototype. */

SET NOCOUNT ON;

IF OBJECT_ID('tempdb..#Hosp2') IS NOT NULL DROP TABLE #Hosp2;
SELECT HospitalId, HospitalCode INTO #Hosp2 FROM dbo.Hospitals;

IF OBJECT_ID('tempdb..#RoomStage') IS NOT NULL DROP TABLE #RoomStage;
CREATE TABLE #RoomStage (ReportDate DATE, HospitalCode VARCHAR(10), RoomCode VARCHAR(20), RoomCategory VARCHAR(150), TotalBeds INT, OccupiedBedsDay INT, OccupiedHoursDay DECIMAL(10,2), OccupiedHoursMTD DECIMAL(12,2));


SELECT s.ReportDate, h.HospitalId, s.RoomCode, s.RoomCategory, s.TotalBeds, s.OccupiedBedsDay, s.OccupiedHoursDay, s.OccupiedHoursMTD
FROM #RoomStage s JOIN #Hosp2 h ON h.HospitalCode = s.HospitalCode
WHERE NOT EXISTS (SELECT 1 FROM dbo.RoomOccupancy ro WHERE ro.ReportDate=s.ReportDate AND ro.HospitalId=h.HospitalId AND ro.RoomCode=s.RoomCode);

DROP TABLE #RoomStage;
DROP TABLE #Hosp2;
